theorem.raw:
\label{t1} Let $T>0$ and let conditions {\rm(i)--(ii)} on $\beta$ and $b$ hold. For each $u_0\in L^\9\cap L^1$, the \FP\ equation \eqref{e1.1} has at most one distributional solution 
\begin{equation}\label{add-e5}
u\in L^1((0,T);L^1)\cap L^\9((0,T)\times\rrd).
\end{equation}

\label{t4} Under hypotheses {\rm(i), (ii), (ii'), (iii)}, for each $u_0\in L^1\cap L^\9$, equation \eqref{e1.1} has a unique distributional solution
\begin{equation}
\label{e2.12}
u\in L^1((0,T);L^1)\cap L^\9((0,T)\times\rrd),\ \ff T>0.
\end{equation}

items.raw:
Consider  the nonlinear \FP\ equation  
\begin{equation}\label{e1.1}
\barr{ll}
u_t-\Delta\beta(u)+{\rm div}(b(x,u)u)=0\mbox{ in }\cald'((0,\9)\times\rr^d),\vsp 
u(0,x)=u_0(x),
\earr\end{equation}
where $\b:\rr\to\rr$ and $b:\rrd\times\rr\to\rrd$ satisfy  the following assumptions
\begin{itemize}
	\item[(i)] {\it$\beta(0)=0$, $\b\in C^1(\rr)$, and 
		\begin{equation}
		\g_0|r_1-r_2|^2\le(\b(r_1)-\b(r_2))(r_1-r_2),\ r_1,r_2\in\rr,\label{e1.2}
			\end{equation}
	where $0<\g_0<\9.$	}
	\item[(ii)] $b\in C_b(\mathbb R^{d+1}; \rrd)$, $b(x, \cdot) \in C^1(\rrd; \rrd)$ $ \forall x\in\rrd$ {\it such that}  $$\mbox{$\sup\{|b^i_r(x,r)|;x\in\rrd,i=1,2,$ $|r|\le M\}\le C_M,$ $\ff M>0.$}$$
	\item[(ii')] $b(x,0)=0$ $\forall x\in\rrd$, $b \in C^1(\mathbb R^{d+1}; \rrd) $ {\it and for
		$$\delta(r):=\sup\{|b_x(x,r)|;\ x\in\rrd\},$$we have} $\delta\in   C_b(\rr).$
\end{itemize}
Here$$b(x,u)=\{b^i(x,u)\}^d_{i=1}\mbox{ and }b^i_r=\frac{\pp b^i}{\pp r}, b_x=\big\{ \nabla_x \, b^i(x, \cdot) \big\}_{i=1}^d.$$
By a distributional solution (in the sense of Schwartz) with initial condition $u_0\in L^1$ we mean a function $u:[0,\9)\to L^1(\rrd)$ such that
$(u(t,\cdot)dx)_{t\in[0,T]}$ is narrowly continuous, that is,
\begin{eqnarray}
&&\lim_{t\to s}\int_{\rrd}u(t,x)\psi(x)dx=\int_{\rrd}u(s,x)\psi(x)dx,\ \ff\psi\in C_b(\rrd),\ s\ge0,\qquad\label{e1.3}\\[2mm]
&&\dd\int^\9_0\int_{\rr^d}(u(t,x)\vf_t(t,x)+\b(u(t,x))\D\vf(t,x)\label{e1.4}\\
&&\qquad+b(x,u(t,x))u(t,x))\cdot\nabla_x\vf(t,x))dt\,dx=0,\nonumber\\
&&\qquad\qquad\qquad\qquad\qquad\qquad\ff\vf\in C^\9_0((0,\9)\times\rr^d).\nonumber
\end{eqnarray}

\begin{equation}
 \label{e2.9}
\barr{l}
(u-|u_0|_\9-\alpha(t))_t-\D(\b(u)-\b(|u_0|_\9+\a(t)))\vsp \qquad
+{\rm div}(b^*(x,u)-b^*(x,|u_0|_\9+\a(t)))\vsp 
\qquad=-{\rm div}(b^*(x,|u_0|_\9+\a(t)))-\a'(t)\le0\mbox{ in }(0,\9)\times\rrd,
\earr
\end{equation}where $\a\in C^1([0,\9))$ is chosen in such a way that
\begin{equation}
\label{e2.

\begin{equation}\label{e2.11aa}
\hspace*{-2mm}\barr{l}
\dd\lim_{\delta\to0}\frac1\delta
\int_{[0<(\beta(u)-\beta(|u_0|_\9+\a(t))^+)\le\delta]}
|b^*(x,u)-b^*(x,|u_0|_\9+\a(t))|\,|\nabla u|dx\vsp
\qquad=\dd\lim_{\delta\to0}\frac1\delta
\int_{[0<(\beta(u)-\beta(|u_0|_\9+\a(t))^+)\le\delta]}
(|b(x,u)-b(x,|u_0|_\9+\a(t))|\,|u|
\vsp\qquad+|b(x,|u_0|_\9+\a(t))|\,|u-|u_0|_\9-\a(t)|)|\nabla u|dx=0,\ \ff t\in(0,T),\earr\end{equation}which is true if $\nabla u\in L^2(0,T;L^2)$ and $b(x,\cdot)\in{\rm Lip}(\rr)$ uniformly in $x$ (which is the case if $b_u\in C_b(\rrd\times\rr))$.

\begin{equation}\label{e2.11aaa}
\barr{l}
u_t-\D(\b(u)+\vp\b(u)+{\rm div}(b_\vp(x,u)u))=0\mbox{ in }(0,T)\times\rrd,\vsp
u(0,x)=u_0(x),\earr\end{equation}where $\vp>0$ and $b_\vp\in C^1_b(\rrd\times\rr)$ is a smooth approximation of $b$.

